<script setup>
import {computed,nextTick,onBeforeUnmount,ref,watch} from 'vue';
import {useRoute} from 'vue-router';
import MarketplaceLayout from '../../layouts/MarketplaceLayout.vue';
import BuyerAccountSidebar from '../../components/account/BuyerAccountSidebar.vue';
import WalletIcon from '../../components/marketplace/WalletIcon.vue';
import {marketplaceRequest as request} from '../../services/marketplace.js';
import {useAuth} from '../../composables/useAuth.js';
import {trapDialogFocus} from '../../utils/dialogFocus.js';
import {lockBodyScroll} from '../../utils/bodyScrollLock.js';
import '../../css/buyer-account.css';
import '../../css/vnd-wallet.css';
const {user}=useAuth(),route=useRoute(),balance=ref(null),history=ref(null),loading=ref(false),historyBusy=ref(false),error=ref(''),historyError=ref(''),detailError=ref(''),selected=ref(null),hide=ref(false),busy=ref(false),notice=ref(''),dialog=ref(null),detailPanel=ref(null),operation=ref('TOP_UP'),amount=ref(''),password=ref(''),pending=ref(null),operationError=ref(''),transaction=ref(null);
const filters=ref({type:'',status:'',from:'',to:''}),applied=ref({...filters.value});
let epoch=0,historyRevision=0,detailRevision=0,opener,unlock,disposed=false;
const kinds={TOP_UP:'Nạp tiền từ ngân hàng',WITHDRAWAL:'Rút tiền về ngân hàng',WALLET_PAYMENT:'Thanh toán đơn hàng',REFUND:'Hoàn tiền vào ví',REVERSAL:'Bút toán đảo'};
const states={PENDING:'Đang xử lý',COMPLETED:'Hoàn thành',FAILED:'Thất bại',CANCELLED:'Đã hủy',REVERSED:'Đã đảo'};
const money=v=>new Intl.NumberFormat('vi-VN',{style:'currency',currency:'VND',maximumFractionDigits:0}).format(v),time=v=>v?new Date(v).toLocaleString('vi-VN'):'Chưa xử lý',enabled=computed(()=>balance.value?.enabled===true);
const storageKey=()=> 'bm:vnd-wallet-request:'+user.value?.id;
function persist(){try{pending.value?sessionStorage.setItem(storageKey(),JSON.stringify(pending.value)):sessionStorage.removeItem(storageKey());}catch{/* Memory identity remains stable when storage is unavailable. */}}
async function load(){const ticket=epoch;loading.value=true;error.value='';try{const b=await request('/account/vnd-wallet');if(ticket!==epoch)return;balance.value=b;if(b.enabled)await loadHistory();}catch(e){if(ticket===epoch){balance.value=null;error.value=e.message;}}finally{if(ticket===epoch)loading.value=false;}}
async function loadHistory(page=0){const ticket=++historyRevision,actor=epoch;historyBusy.value=true;historyError.value='';try{const h=await request('/account/vnd-wallet/transactions?'+new URLSearchParams({page,...applied.value}));if(ticket!==historyRevision||actor!==epoch)return;history.value=h;}catch(e){if(ticket===historyRevision&&actor===epoch)historyError.value=e.message;}finally{if(ticket===historyRevision&&actor===epoch)historyBusy.value=false;}}
function filter(reset=false){if(reset)filters.value={type:'',status:'',from:'',to:''};applied.value={...filters.value};selected.value=null;loadHistory();}
async function detail(id,focus=true){const ticket=++detailRevision,actor=epoch;selected.value=null;detailError.value='';try{const t=await request('/account/vnd-wallet/transactions/'+encodeURIComponent(id));if(ticket!==detailRevision||actor!==epoch)return;selected.value=t;if(focus){await nextTick();detailPanel.value?.focus({preventScroll:true});}}catch(e){if(ticket===detailRevision&&actor===epoch)detailError.value=e.message;}}
async function bank(){if(busy.value)return;const ticket=epoch;busy.value=true;notice.value='';try{await request('/account/vnd-wallet/test-bank','POST',{},false);if(ticket===epoch){notice.value='Đã tạo tài khoản nhận mô phỏng. Đây không phải liên kết hoặc xác minh ngân hàng thật.';await load();}}catch(e){if(ticket===epoch)notice.value=e.message;}finally{if(ticket===epoch)busy.value=false;}}
async function open(type,event){operation.value=pending.value?.type||type;operationError.value='';transaction.value=null;password.value='';amount.value=pending.value?.amount||'';opener=event.currentTarget;unlock=lockBodyScroll();dialog.value.showModal();await nextTick();dialog.value.querySelector('input')?.focus();}
function closed(){unlock?.();unlock=undefined;password.value='';opener?.isConnected&&opener.focus({preventScroll:true});}
function cancel(event){if(busy.value)event.preventDefault();}
async function create(){
 if(busy.value)return;const actor=epoch;busy.value=true;operationError.value='';
 try{
 if(!pending.value){pending.value={type:operation.value,amount:amount.value,requestKey:crypto.randomUUID()};persist();}
 const identity=pending.value,recovered=await request('/account/vnd-wallet/requests/'+identity.requestKey);if(actor!==epoch)return;
 const saved=recovered.transaction||await request('/account/vnd-wallet/requests','POST',{...identity,password:password.value},false);if(actor!==epoch)return;
 transaction.value=saved;pending.value=null;persist();password.value='';await load();
 }catch(e){if(actor===epoch){operationError.value=e.message;if([400,403,409,429].includes(e.status)){pending.value=null;persist();}}}
 finally{if(actor===epoch)busy.value=false;}
}
async function simulate(outcome){
 if(busy.value||!transaction.value)return;const ticket=epoch,id=transaction.value.id;busy.value=true;operationError.value='';
 try{const current=await request('/account/vnd-wallet/transactions/'+id);if(ticket!==epoch)return;const t=current.status!=='PENDING'?current:await request('/account/vnd-wallet/transactions/'+id+'/simulate','POST',{outcome},false);if(ticket!==epoch)return;transaction.value=t;await load();await detail(id,false);}
 catch(e){if(ticket===epoch)operationError.value=e.message;}
 finally{if(ticket===epoch)busy.value=false;}
}
function historyScroll(){document.getElementById('bm-wallet-history')?.scrollIntoView({block:'start'});}
watch(()=>user.value?.id,()=>{epoch++;historyRevision++;detailRevision++;balance.value=null;history.value=null;selected.value=null;pending.value=null;busy.value=false;dialog.value?.close();try{const old=JSON.parse(sessionStorage.getItem(storageKey())||'null');if(old&&['TOP_UP','WITHDRAWAL'].includes(old.type)&&/^[a-f0-9-]{36}$/.test(old.requestKey))pending.value=old;}catch{/* Invalid stored data is never treated as a receipt. */}if(user.value)load();},{immediate:true});
watch(()=>route.query.transaction,id=>{if(id&&enabled.value)detail(String(id));});
watch(enabled,value=>{if(value&&route.query.transaction)detail(String(route.query.transaction));});
onBeforeUnmount(()=>{disposed=true;epoch++;historyRevision++;detailRevision++;dialog.value?.close();unlock?.();});
</script>
<template><MarketplaceLayout><main class="bm-wallet-page">
 <header class="bm-wallet-hero"><div><h1>Ví BonsaiMarket</h1><p>Quản lý số dư VND thử nghiệm và theo dõi các giao dịch của bạn.</p></div></header>
 <div class="bm-wallet-body">
 <p class="bm-wallet-sandbox" role="note"><WalletIcon name="info"/> Chế độ thử nghiệm — Tiền mô phỏng, không có giá trị thanh toán thực tế.</p>
 <div v-if="error" class="bm-wallet-error" role="alert">{{ error }} <button type="button" @click="load">Thử tải lại</button></div>
 <p v-if="loading&&!balance" class="bm-wallet-skeleton" role="status">Đang tải số dư và lịch sử ví…</p>
 <div class="bm-wallet-overview"><BuyerAccountSidebar wallet/>
 <section class="bm-wallet-main" aria-label="Tổng quan ví">
 <div class="bm-wallet-balance"><div><h2>Số dư khả dụng <button type="button" :aria-label="hide?'Hiện số dư':'Ẩn số dư'" :aria-pressed="hide" @click="hide=!hide"><WalletIcon name="eye"/></button></h2><strong>{{ enabled?(hide?'••••••':money(balance.available)):'Chưa khả dụng' }}</strong><p v-if="enabled">Đang giữ: {{ hide?'••••':money(balance.held) }}</p><p><WalletIcon name="shield"/> Sổ giao dịch VND thử nghiệm của BonsaiMarket</p></div><WalletIcon class="bm-wallet-balance-art" name="wallet"/></div>
 <div class="bm-wallet-actions"><button type="button" :disabled="!enabled||busy" @click="open('TOP_UP',$event)"><WalletIcon name="plus"/>Nạp tiền</button><button type="button" :disabled="!enabled||busy" @click="open('WITHDRAWAL',$event)"><WalletIcon name="withdraw"/>Rút tiền</button><button type="button" disabled aria-describedby="bm-wallet-transfer-note"><WalletIcon name="transfer"/>Chuyển tiền</button><button type="button" :disabled="!enabled" @click="historyScroll"><WalletIcon name="clock"/>Lịch sử giao dịch</button></div>
 <p id="bm-wallet-transfer-note" class="bm-wallet-muted">Chuyển ví–ví chưa được mở trong phạm vi thử nghiệm này.</p>
 <div class="bm-wallet-card bm-wallet-bank"><span class="bm-wallet-symbol"><WalletIcon name="bank"/></span><div><h2>Tài khoản ngân hàng đã liên kết</h2><p v-if="balance?.bank?.display_name">{{ balance.bank.display_name }} · {{ balance.bank.masked_number }} <span class="bm-wallet-badge">Mô phỏng</span></p><p v-else>Chưa có tài khoản nhận mô phỏng.</p></div><button type="button" :disabled="!enabled||busy" @click="bank">{{ balance?.bank?.display_name?'Cập nhật':'Tạo tài khoản thử nghiệm' }} <WalletIcon name="chevron"/></button></div>
 <p v-if="balance&&!enabled" class="bm-wallet-muted">Ví chưa mở trên môi trường này. Cần môi trường QA cô lập và quyền thử nghiệm do đội vận hành cấp.</p>
 <p v-if="pending" role="status">Có yêu cầu chưa rõ kết quả. <button type="button" @click="open(pending.type,$event)">Tra cứu yêu cầu đang chờ</button></p>
 <p v-if="notice" class="bm-wallet-muted" role="status">{{ notice }}</p>
 </section>
 <aside class="bm-wallet-info"><section class="bm-wallet-card"><h2><WalletIcon name="info"/> Về ví BonsaiMarket</h2><p>Ví VND thử nghiệm dùng để:</p><ul><li><WalletIcon name="check"/> Nạp tiền qua bộ mô phỏng.</li><li><WalletIcon name="check"/> Thanh toán đơn hàng trong QA.</li><li><WalletIcon name="check"/> Nhận hoàn tiền khi hủy đơn hợp lệ.</li></ul><RouterLink to="/banner-credits">Credit quảng bá / banner được quản lý riêng <WalletIcon name="arrow"/></RouterLink></section><section class="bm-wallet-card"><h2><WalletIcon name="shield"/> Bảo mật giao dịch</h2><ul><li><WalletIcon name="lock"/> Xác nhận mật khẩu khi rút thử nghiệm.</li><li><WalletIcon name="shield"/> Kiểm tra số dư trước khi thanh toán.</li><li><WalletIcon name="clock"/> Lưu đầy đủ lịch sử giao dịch.</li></ul><p class="bm-wallet-muted">Không có liên kết ngân hàng hoặc xử lý tiền thật.</p></section></aside>
 </div>
 <div class="bm-wallet-history-layout">
 <section id="bm-wallet-history" class="bm-wallet-card bm-wallet-history" aria-labelledby="bm-wallet-history-title"><div class="bm-wallet-heading"><h2 id="bm-wallet-history-title"><WalletIcon name="list"/>Lịch sử giao dịch</h2><button type="button" :disabled="!enabled||historyBusy" @click="loadHistory(history?.page||0)"><WalletIcon name="refresh"/>Làm mới</button></div>
 <form class="bm-wallet-filters" @submit.prevent="filter()"><label>Loại giao dịch<select v-model="filters.type" :disabled="!enabled"><option value="">Tất cả</option><option v-for="(label,key) in kinds" :key="key" :value="key">{{ label }}</option></select></label><label>Trạng thái<select v-model="filters.status" :disabled="!enabled"><option value="">Tất cả</option><option v-for="(label,key) in states" :key="key" :value="key">{{ label }}</option></select></label><label>Từ ngày (UTC)<input v-model="filters.from" type="date" :disabled="!enabled"/></label><label>Đến ngày (UTC)<input v-model="filters.to" type="date" :disabled="!enabled"/></label><button :disabled="!enabled||historyBusy">Lọc</button><button type="button" :disabled="!enabled||historyBusy" @click="filter(true)">Đặt lại</button></form>
 <p v-if="historyBusy" role="status">Đang tải lịch sử…</p><p v-if="historyError" class="bm-wallet-error" role="alert">{{ historyError }} <button @click="loadHistory(history?.page||0)">Thử lại</button></p>
 <div v-if="history&&!historyError" class="bm-wallet-table-wrap"><table><thead><tr><th>Thời gian</th><th>Giao dịch</th><th>Số tiền</th><th>Trạng thái</th><th>Mã tham chiếu</th><th><span class="bm-wallet-sr">Chi tiết</span></th></tr></thead><tbody><tr v-for="row in history.content" :key="row.id" :class="{'bm-wallet-selected':selected?.id===row.id}"><td><time :datetime="row.createdAt">{{ time(row.createdAt) }}</time></td><td><strong>{{ kinds[row.type] }}</strong><small v-if="row.orderId">Đơn hàng #{{ row.orderId }}</small></td><td :class="{'bm-wallet-positive':row.signedAmount>0}"><strong>{{ row.signedAmount>0?'+':'' }}{{ money(row.signedAmount) }}</strong></td><td><span class="bm-wallet-badge" :data-status="row.status">{{ states[row.status] }}</span></td><td><span class="bm-wallet-reference" :title="row.id">{{ row.id.slice(0,8) }}</span></td><td><button type="button" :aria-label="'Xem giao dịch '+row.id" @click="detail(row.id)">Xem</button></td></tr></tbody></table></div>
 <p v-if="history&&!history.content.length&&!historyError" class="bm-wallet-empty">Không có giao dịch khớp bộ lọc. Giao dịch chỉ xuất hiện sau khi tạo yêu cầu trong sandbox.</p><p v-if="!enabled&&!loading" class="bm-wallet-empty">Lịch sử chỉ khả dụng khi ví thử nghiệm được bật.</p>
 <nav v-if="history?.totalPages>1" class="bm-wallet-pagination" aria-label="Phân trang giao dịch"><span>{{ history.totalElements }} giao dịch</span><button :disabled="historyBusy||history.page===0" @click="loadHistory(history.page-1)">Trước</button><span>{{ history.page+1 }} / {{ history.totalPages }}</span><button :disabled="historyBusy||history.page+1>=history.totalPages" @click="loadHistory(history.page+1)">Sau</button></nav>
 </section>
 <Transition name="bm-wallet-detail"><aside v-if="selected||detailError" ref="detailPanel" class="bm-wallet-card bm-wallet-detail" tabindex="-1" aria-label="Chi tiết giao dịch"><div class="bm-wallet-heading"><h2>Chi tiết giao dịch</h2><button type="button" aria-label="Đóng chi tiết" @click="selected=null;detailError='';detailRevision++"><WalletIcon name="close"/></button></div><p v-if="detailError" role="alert">{{ detailError }}</p><template v-if="selected"><div class="bm-wallet-detail-summary"><span class="bm-wallet-symbol"><WalletIcon :name="selected.signedAmount>0?'plus':'withdraw'"/></span><h3>{{ kinds[selected.type] }}</h3><span class="bm-wallet-badge" :data-status="selected.status">{{ states[selected.status] }}</span><strong>{{ selected.signedAmount>0?'+':'' }}{{ money(selected.signedAmount) }}</strong></div><dl><dt>Mã giao dịch</dt><dd>{{ selected.id }}</dd><dt>Thời gian</dt><dd>{{ time(selected.createdAt) }}</dd><dt>Xử lý lúc</dt><dd>{{ time(selected.processedAt) }}</dd><dt>Đơn vị</dt><dd>VND · mô phỏng</dd><template v-if="selected.reference"><dt>Tham chiếu mô phỏng</dt><dd>{{ selected.reference }}</dd></template><template v-if="selected.orderId"><dt>Đơn hàng</dt><dd><RouterLink :to="'/orders/'+selected.orderId">#{{ selected.orderId }}</RouterLink></dd></template><template v-if="selected.balanceAfter!==null"><dt>Số dư sau giao dịch</dt><dd>{{ money(selected.balanceAfter) }}</dd></template></dl><p class="bm-wallet-muted">{{ selected.explanation }}</p><button v-if="selected.status==='PENDING'&&['TOP_UP','WITHDRAWAL'].includes(selected.type)" type="button" @click="open(selected.type,$event);transaction=selected">Mở bộ mô phỏng</button></template></aside></Transition>
 </div>
 </div>
 <dialog ref="dialog" class="bm-wallet-dialog" aria-labelledby="bm-wallet-action-title" @keydown.tab="trapDialogFocus" @cancel="cancel" @close="closed"><h2 id="bm-wallet-action-title">{{ operation==='TOP_UP'?'Nạp tiền thử nghiệm':'Rút tiền thử nghiệm' }}</h2><p class="bm-wallet-sandbox">Chế độ thử nghiệm — Tiền mô phỏng, không có giá trị thanh toán thực tế.</p><p v-if="operationError" class="bm-wallet-error" role="alert">{{ operationError }}</p>
 <form v-if="!transaction" @submit.prevent="create"><label>Số tiền (VND)<input v-model="amount" type="number" inputmode="numeric" min="1000" max="10000000" step="1" required :readonly="!!pending" :disabled="busy"/></label><p>Giới hạn 1.000–10.000.000 VND/lần, 50.000.000 VND/ngày cho mỗi loại.</p><template v-if="operation==='WITHDRAWAL'"><p>Tài khoản nhận: {{ balance?.bank?.display_name||'Chưa có tài khoản nhận mô phỏng' }} {{ balance?.bank?.masked_number||'' }}</p><label>Mật khẩu tài khoản QA<input v-model="password" type="password" autocomplete="current-password" maxlength="200" :disabled="busy" :required="!pending"/></label><p>Xác nhận mật khẩu cho lần tạo yêu cầu rút. Không phải OTP ngân hàng.</p></template><button class="bm-wallet-primary" :disabled="busy||!enabled">{{ busy?'Đang xác minh…':pending?'Tra cứu & tiếp tục cùng yêu cầu':'Tạo yêu cầu thử nghiệm' }}</button></form>
 <div v-else><h3>{{ kinds[transaction.type] }} · {{ money(transaction.amount) }}</h3><p role="status">{{ states[transaction.status] }}</p><p class="bm-wallet-reference">{{ transaction.id }}</p><template v-if="transaction.status==='PENDING'"><p>Chưa có xác nhận. Nạp tiền chưa cộng số dư; rút tiền chỉ giữ khoản đã yêu cầu. Chọn kết quả từ bộ mô phỏng nội bộ:</p><div class="bm-wallet-dialog-actions"><button class="bm-wallet-primary" :disabled="busy" @click="simulate('COMPLETED')">Mô phỏng hoàn tất</button><button :disabled="busy" @click="simulate('FAILED')">Mô phỏng thất bại</button></div></template><p v-else>Giao dịch mô phỏng đã kết thúc. Xem lịch sử để đối chiếu.</p></div><div class="bm-wallet-dialog-actions"><button type="button" :disabled="busy" @click="dialog.close()">Đóng</button></div></dialog>
</main></MarketplaceLayout></template>